solutionCode:
function resolveSegments(template, path) {
  const templateParts = template.split('/').filter(Boolean);
  const pathParts = path.split('/').filter(Boolean);
  const params = {};

  if (templateParts.length !== pathParts.length) return null;

  for (let i = 0; i < templateParts.length; i++) {
    const tPart = templateParts[i];
    const pPart = pathParts[i];

    if (tPart.startsWith('[') && tPart.endsWith(']')) {
      const key = tPart.slice(1, -1);
      params[key] = pPart;
    } else if (tPart !== pPart) {
      return null; // Route mismatch
    }
  }

  return params;
}

