description:
Write a function `parseToolCall(geminiPayload, localTools)` that dynamically processes a Gemini API tool calling tool response.

### Requirements
Given `geminiPayload` containing:
```json
{
  "functionCall": {
    "name": "calculateStreak",
    "args": { "userId": 102 }
  }
}
```
And `localTools` (a lookup object containing local JS functions like `{ calculateStreak: (args) => { return args.userId + '-streak'; } }`):

Extract the function name, assert that it exists in `localTools`, execute it passing its arguments, and return the result.
- If the function doesn't exist, return `"Invalid tool call"`.

starterCode:
function parseToolCall(geminiPayload, localTools) {
  // Write your code here
  return null;
}

solutionCode:
function parseToolCall(geminiPayload, localTools) {
  const call = geminiPayload.functionCall;
  if (!call || !call.name) return 'Invalid tool call';

  const func = localTools[call.name];
  if (typeof func !== 'function') {
    return 'Invalid tool call';
  }
  return func(call.args);
}

